/// <param name = "_formControl">FormControl</param>
/// <param name = "_filterStr">str</param>
public void lookup(FormControl _formControl, str _filterStr)
{
    if (!NDXBVEMailRequestLineItem.ItemIdDataAreaId)
    {
        NDXBVEMailRequestLineItem.ItemIdDataAreaId = curExt();
    }
    NDXHelperItem::lookupItemInCompany(_formControl, _filterStr, NDXBVEMailRequestLineItem.ItemIdDataAreaId);
}

